//! Embedded, pre-decoded artwork and colours (generated by `build.rs`).
//!
//! Nothing here is parsed at run time: the mark is premultiplied RGBA, the
//! wordmark and the glyphs are coverage bytes, and the colours come from the
//! Boswas UI token file (`desktop/ui/tokens.json`).

use crate::gfx::Rgb;

/// One glyph of the atlas, in pixels at [`GLYPH_PX`].
#[derive(Clone, Copy, Debug)]
pub struct Glyph {
    /// Start of the `width * height` coverage bytes in [`GLYPH_A8`].
    pub offset: usize,
    pub width: usize,
    pub height: usize,
    /// Horizontal offset of the bitmap from the pen position.
    pub left: i32,
    /// Offset of the bitmap's bottom edge above the baseline.
    pub bottom: i32,
    /// Pen advance.
    pub advance: f32,
}

include!(concat!(env!("OUT_DIR"), "/assets.rs"));

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn embedded_assets_are_consistent() {
        assert_eq!(MARK_RGBA.len(), (MARK_WIDTH * MARK_HEIGHT * 4) as usize);
        assert_eq!(WORDMARK_A8.len(), (WORDMARK_WIDTH * WORDMARK_HEIGHT) as usize);
        assert_eq!(GLYPHS.len(), (GLYPH_LAST - GLYPH_FIRST + 1) as usize);
        for g in GLYPHS.iter() {
            assert!(g.offset + g.width * g.height <= GLYPH_A8.len());
            assert!(g.advance > 0.0);
        }
        // The mark is premultiplied: no colour channel exceeds alpha.
        for px in MARK_RGBA.chunks_exact(4) {
            assert!(px[0] <= px[3] && px[1] <= px[3] && px[2] <= px[3]);
        }
        // It has both transparent and opaque pixels, and the wordmark has ink.
        assert!(MARK_RGBA.chunks_exact(4).any(|p| p[3] == 0));
        assert!(MARK_RGBA.chunks_exact(4).any(|p| p[3] == 255));
        assert!(WORDMARK_A8.contains(&255));
    }

    #[test]
    fn palette_comes_from_the_token_file() {
        // desktop/ui/tokens.json: ink.950 and iris.400.
        assert_eq!(BACKGROUND, Rgb::new(0x0B, 0x0A, 0x12));
        assert_eq!(ACCENT, Rgb::new(0x9B, 0x8A, 0xFF));
    }
}
